{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance is potentially exposed to the public internet because it is not explicitly configured to not have a public IP address."
    },
    {
      "check_id": "AVD-AWS-0028",
      "title": "Instance does not require IMDS access to require a token",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "HIGH",
      "explanation": "Instance metadata service can be interacted with freely, potentially allowing unauthorized access to instance metadata."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not have an IAM role attached, potentially limiting its ability to interact with other AWS resources securely."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"MyFirstInstnace\" {\n  ami           = lookup(var.AMIS, var.AWS_REGION)\n  instance_type = \"t2.micro\"\n  availability_zone = \"us-east-2a\"\n  key_name      = aws_key_pair.levelup_key.key_name\n  vpc_security_group_ids = [aws_security_group.allow-levelup-ssh.id]\n  subnet_id = aws_subnet.levelupvpc-public-1.id\n  iam_instance_profile = aws_iam_instance_profile.example.name\n  metadata_options {\n    http_tokens = \"required\"\n  }\n  associate_public_ip_address = false\n}",
  "fix_summary": "Added iam_instance_profile to attach an IAM role, set http_tokens to 'required' for IMDSv2, and set associate_public_ip_address to false to prevent public IP assignment."
}
